import json,pathlib
HERE=pathlib.Path(__file__).parent;P='additional_rust_functional_certifiers'
p=HERE/(P+'_notes.json');d=json.loads(p.read_text())
notes={
'code/rust/core_certifiers/src/phi1_certifier.rs':'Full500-line read. Generic max-form LP checker validates dimensions, x/y nonnegativity, Ax<=b, A^Ty>=c and exact equality of objectives, returning a private serialize-only certificate that retains all submitted vectors. Correct weak-duality interpretation for valid canonical rationals; no algorithm finds a witness. Generic path omits zero-denominator validation of public BigRational::new_raw inputs (RFC-F001, probe pending). Separate Phi1FormCertificate delegates to functional replay_form, explicitly assuming supplied residual is from an achiever and coboundaries form a spanning family; no original omega/d/alpha is bound by this form. Zero weights are admissible seminorms, unlike strict-positive exact quotient owner. Lean paths/hashes/theorem/allowed-axiom strings are source-binding metadata, explicitly not native Lean replay. No allocation/bit/fuel ceilings. Three meaningful form tests read; no fresh execution yet. No deserialization bypass for sealed Phi1Certificate.',
'code/rust/core_functional/src/phi1.rs':'Full1196-line read. Sealed VerifiedExactPhi1 has private certificate and read-only access, no Deserialize; verification validates all rational denominators and dimensions, positive weights, residual=omega-d0alpha, annihilating dual and weighted infinity bound, then exact primal/dual equality. This is attained quotient optimality for the supplied finite rational presentation, not authority or external-carrier adequacy. Form replay permits nonnegative weights and assumes complete supplied generators. i128 mass uses checked operations; stack rational helper delegates bounded arithmetic and overloads Overflow for shape/negative-weight refusals. Floating mass is explicitly diagnostic, not quotient evidence. diagnose_primal_dual checks finite inputs/scalar outputs but f64::max can discard NaN in a boundary vector (RFC-F002, probe pending). Binary exact search exhausts source dim<=20 and special-cases larger image membership/weight<=1; Gray image-basis enumeration reports exact only when all states fit budget, with rank>=64 saturation retained as inexact. u8 matrix/vector coordinates are reduced modulo2; no claim of strict wire admission. Rational bit growth and matrix allocations are unbounded at this public owner. Concrete tests independently alter every certificate field/zero denominator, check arithmetic overflow, float cases, and8 binary residuals vs independent4-state exhaustion. No fresh tests in this checkpoint.',
'code/rust/core_functional/src/binary_degree.rs':'Full179-line read. Exact Boolean shape-checked row elimination decides image membership and counts nonzero entries of a supplied composite. Caller must construct and bind the intended d1d0; chain_composite_weight is not quotient Phi1. Shared shape/input-length helpers precede internal unchecked Gaussian elimination. MAX_EXHAUSTIVE_BINARY_DOMAIN_DIM20 is used by Phi1 search, not a general row/column work cap here. Empty/ragged cases have ordinary finite linear algebra interpretation; no nilpotence certificate or witness returned by membership bool. Three owner-related tests cover quotient/closure distinction, integer Gamma2 overflow and composite shape/count. No fresh execution yet.',
'code/rust/core_certifiers/src/authority_minting.rs':'Full129-line read. Deprecated compatibility export now forwards to evidence-only packet certification. GuardCensus accepts effect None/Refused, refuses Certified/other strings, and counts seven supplied booleans or a none-record. It neither recomputes guard propositions nor checks effect/terminal/firewall/guard consistency or nonempty witnesses. Private census fields prevent mutation but establish only this count/label predicate. Two direct tests cover mixed seven guards and Certified rejection. Naming retained for compatibility; no authority constructor is present.',
'code/rust/core_certifiers/src/certificate_boundary.rs':'Full311-line read, including re-read of truncated tail. serialize/deserialize AuthorityVerdict is mutable public diagnostic DTO; from_certificate copies terminal/guards/replay hash while forcing effect None, none_record omits evidence. certify_checked_packet delegates to sealed evidence contract, constructs no CertifiedAuthority. Caller may forge DTO strings, so admit_verdict/count checks are not authentication. Tests construct real exact Phi1/Gamma2/trichotomy and verify None posture and packet replay hash; source-read only. Shared count/capacity record and historical killed6 comment are not proof of packet soundness.',
'code/rust/core_certifiers/src/checked_packet.rs':'Full554-line read; missing initial lines from a truncated batched output were explicitly re-read. Private serialize-only CheckedPacket requires typed exact Phi1/trichotomy, nonempty evidence/checker and nonzero replay/certificate refs, Verified label, and equality of Phi1 scalar. It copies all other caller hashes/scope without recomputing bindings and does not establish the two typed witnesses concern the same carrier/residual (RFC-F003). certify_evidence admits only ExactRepair and checks witness replay hash before delegating to core_contracts terminal/guard seal; result remains AuthorityEffect None. Replay hash/packet ID are caller supplied, so equal hashes across distinct args do not prove byte custody. Tests cover missing cert refs, witness hash/terminal mismatch and nonexact statuses, but use fabricated placeholder hashes rather than independently serialized carrier/certificate data. No provider/state mutation and no new execution.'}
for k,v in notes.items():
 if k in d:assert d[k]==v
 else:d[k]=v
p.write_text(json.dumps(d,indent=2)+'\n')
def ev(path,a,b):return {'path':path,'lines':[a,b]}
supp={'claims':[{'id':'RFC-C001','claim':'The full exact Phi1 checker seals an attained weighted rational quotient minimum by primal-dual equality on the supplied presentation.','evidence':[ev('code/rust/core_functional/src/phi1.rs',316,409)],'dependencies':['Nonzero rational denominators; matching dimensions; positive weights; exact arithmetic; declared d0/omega carrier'],'limitations':['No independently justified adapter, authority, physical selection or bit/resource bound. Form replay separately assumes spanning generators.']},{'id':'RFC-C002','claim':'Checked-packet certification preserves a None authority effect and delegates terminal/guard consistency to a sealed contract.','evidence':[ev('code/rust/core_certifiers/src/certificate_boundary.rs',25,67),ev('code/rust/core_certifiers/src/checked_packet.rs',237,263)],'dependencies':['Typed Phi1/trichotomy; caller packet/replay references; core_contracts seal and core_types guards'],'limitations':['Reference byte authenticity and cross-carrier provenance are not verified here; AuthorityVerdict DTO is unsealed metadata.']}],
'findings':[{'id':'RFC-F001','severity':'medium','title':'Generic LP verifier omits raw rational denominator admission','evidence':[ev('code/rust/core_certifiers/src/phi1_certifier.rs',221,317)],'status':'source-established omission; bounded probe pending','detail':'Unlike the full Phi1 and form paths, generic Phi1Verifier performs comparisons/arithmetic on public BigRational inputs without rejecting zero denominators. BigRational::new_raw permits those values. Validate denominators before comparisons and add typed-refusal tests.','limits':'Do not yet claim a reproduced panic or forged certificate.'},{'id':'RFC-F002','severity':'medium','title':'Floating dual-boundary maximum can hide arithmetic NaN','evidence':[ev('code/rust/core_functional/src/phi1.rs',629,659)],'status':'source-established mechanism; bounded probe pending','detail':'Finite d0 and dual values can overflow products to opposite infinities, summing to NaN in d0^T dual; fold(0,f64::max) discards NaN. The final finite scalar checks may therefore return a zero boundary defect. Check every intermediate residual/boundary entry before reductions.','limits':'Diagnostic API only; no exact-certificate or authority promotion asserted.'},{'id':'RFC-F003','severity':'medium','title':'CheckedPacket compares witness values without binding their carrier identities','evidence':[ev('code/rust/core_certifiers/src/checked_packet.rs',162,214)],'status':'source-established','detail':'new_checked compares trichotomy.phi1_value to verified_phi1.value only, then copies arbitrary nonzero certificate refs and caller carrier/boundary/weights/defect hashes. Equal values from unrelated presentations can populate one apparently checked packet. Require source/certificate bindings or document and encode an explicit trusted admission layer that establishes them.','limits':'Sealed result retains FactOnly and later certificate retains None; no runtime authority exploit claimed. Parent core_policy review may supply additional downstream constraints.'}],
'validation':[{'id':'RFC-V001','kind':'source custody','result':'Frozen64 paths match original8050 inventory; all current source hashes rechecked by checkpoint builder.','limits':'Hash checks do not establish semantic reading; only notes do.'}]}
sp=HERE/(P+'_supplement.json')
